%   Inputs:
%   efc   equivalent full cycles [-]
%   days  days in service [d]
%   T     mean cell temperature [degC]
%   m     mean SOC [0-1]
%   dod   typical depth of discharge [0-1]
%   rr    resistance ratio R/R_BoL [-]

%#codegen
soh = 1.0;
if rr <= 1.093562
